import fs from 'node:fs';
const root='reports/local/g03-farm-minor-20261023',summary=JSON.parse(fs.readFileSync(root+'/summary-live.json','utf8'));
const counts=a=>a.reduce((o,k)=>(o[k]=(o[k]??0)+1,o),{}),round=n=>Math.round(n*1000)/1000;
const rows=summary.rows.map(r=>{const d=JSON.parse(fs.readFileSync(r.file,'utf8')),p=d.pressure.filter(x=>Number(x.stage.split(':')[1])>=12);return {id:r.id,stop:r.stop,stage:r.stage,finalNotice:d.final.notice,finalStageElapsed:d.final.stageElapsed,deaths:r.deathEvents,deathsByStage:counts(d.deathRows.map(u=>u.stage)),deathsByType:counts(d.deathRows.map(u=>u.type)),heroDeathEvents:r.heroDeathEvents,repairs:[r.repairMinerals,r.repairGas],revivals:r.paidHeroRevivals,bodyDelivery:r.deliveries,passengerLossReasons:r.deliveryLossReasons,training:[r.trainingCards,r.actualUnitRankIncreases],minUnitsSince12:p.length?Math.min(...p.map(x=>x.units)):null,samplesAtTwoOrLess:p.filter(x=>x.units<=2).length,lowHpFraction:p.length?round(p.filter(x=>x.hpFraction<.5).length/p.length):null,finalArmy:r.finalAllies.map(u=>({type:u.type,rank:u.rank,hero:u.hero,hpFraction:round(u.hp/u.maxHp)})),heroes:r.heroes.map(h=>({id:h.id,rank:h.rank})),openingQuality:r.openingQuality,finalQuality:r.finalQuality,changedSlots:r.changedSlots,stageEnds:r.stageEnds.map(s=>({stage:s.stage,units:s.units,seconds:s.stageElapsed}))};});
fs.writeFileSync(root+'/pressure-analysis.json',JSON.stringify({scope:'Selected final-cohort rows only, still provisional while missing rows exist. One-second samples do not equal precise duration or individual-unit health minima.',missing:summary.missing,rows},null,2));
console.log(JSON.stringify(rows.map(({finalArmy,stageEnds,...r})=>({...r,finalUnits:finalArmy.length})),null,2));
